// TH14 v1.00b Extra Boss7 7th nonspell, st07bs.ecl.txt:676-729.
// Card frame 0 = control spawn; the real boss starts after the 120-frame
// opening buffer. Source clock 0 = Boss7 entry (timerReset at 689); the
// slot0 timeout (3000) stops both emitters. Boundary attack BossCard7
// (setInterrupt at 709; 1887-1931) is not started.

const TIME_LIMIT: int = 3424;
const OPENING_BUFFER: int = 120;
const SOURCE_END: int = 3000;

// transcribe/th14/touhou-bullets.ecl mapping:
// source type8/color8 -> TH14_RICE, source type5/color6 -> TH14_BALL2.
const TH14_RICE: int = 480;
const TH14_BALL2: int = 432;

// st07bs 731-761 Boss7_at, emitter 0:
// etAim(10) fixed alternating-layer ring, etCount(7,7), etAngle(A,delta),
// etSpeed(3.0->2.5), etEx ANIM a=1, etDist 16, etOffset(0,24).
sub fire_burst_at(ang: int) {
    for q in 0..7 {
        var hv: int = ((q+1)/2)*341;          // delta 0.032724924 rad
        var kk: int = ((q+1)/2)*2;            // speed index k=(q+1)&~1
        var sp: fx = 3fx - (kk as fx) * 0.5fx / 6fx;
        for i in 0..7 {
            var base: int = (i*65536)/7 + hv;
            var a: int = ang + base;
            if q % 2 != 0 { a = ang - base; }
            var aa: angle = a as angle;
            // etDist 16 minus ANIM birth shift 4*speed, along this bullet's angle.
            var net: fx = 16fx - 4fx*sp;
            var x: fx = $self_x + net*cos(aa);
            var y: fx = $self_y + 24fx + net*sin(aa);
            _ = fire(TH14_RICE, 8, x, y, sp, aa, none, none);
        }
    }
}

async sub boss7_at() {
    var ang: int = rand(65536) - 32768;       // %RANDRAD at 743
    var step: int = 40504;                    // %B = 3.883222 rad at 744
    loop {
        for burst in 0..8 {                   // D=8 inner fires at 748/756
            if self_int(1) == 1 { return; }
            fire_burst_at(ang);
            ang = ang + step;                 // 753
            wait(17);                         // 754
        }
        step = 0 - step;                      // %B = %B * -1 at 757
    }
}

// st07bs 763-793 Boss7_at2, emitter 1:
// etAim(3) fixed ring, etCount(6,1), etSpeed(4.0), ANIM a=1 + BRIGHT;
// circlePos base offset + per-shot etOffsetRad, etAngle(C, 30deg).
async sub boss7_at2() {
    var c: int = rand(65536) - 32768;         // %C = %RANDRAD at 774
    loop {
        if self_int(1) == 1 { return; }
        // circlePos(%A,%B,%RANDRAD,%RANDF*16) at 778.
        var th: int = rand(65536) - 32768;
        var rr: fx = ((rand(65536) - 32768) as fx) / 4096fx + 8fx;
        var ta: angle = th as angle;
        var bx: fx = $self_x + rr*cos(ta);
        var by: fx = $self_y + rr*sin(ta);
        for f in 0..10 {                      // $F = 10 at 781
            // etOffsetAbs(1, A+FINAL_X, B+FINAL_Y) at 779 plus
            // etOffsetRad(1, %RANDRAD, %RANDF*8) at 784.
            var th2: int = rand(65536) - 32768;
            var rr2: fx = ((rand(65536) - 32768) as fx) / 8192fx + 4fx;
            var px: fx = bx + rr2*cos(th2 as angle);
            var py: fx = by + rr2*sin(th2 as angle);
            for i in 0..6 {                   // etCount(6,1)
                var a: int = c + (i*65536)/6;
                var aa: angle = a as angle;
                // ANIM shift 4*velocity (speed 4.0) along this bullet's angle.
                var x: fx = px - 16fx*cos(aa);
                var y: fx = py - 16fx*sin(aa);
                _ = fire(TH14_BALL2, 6, x, y, 4fx, aa, none, none);
            }
        }
        c = c - 1820;                         // %C -= 0.174533 rad at 788
        wait(5);                              // 789
    }
}

// moveRand(60,4,1.0) with moveLimit(0,128,280,64) from TH16 movement.md:
// actual bounds x in [-140,140], y in [96,160]; direction inner zone
// |x| < 70, y in (112,144); speed 1.0*(1-k/60), no bounce.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60-k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0)*speed;
    var ny: fx = $self_y + self_fx(1)*speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

sub card_move_rand() {
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -70fx {
        a = r/3;
    } else if $self_x > 70fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; }
    } else {
        a = r/4;
        var choose: int = rand(65536)%3;
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

async sub boss7_main() {
    set_invuln(65535);
    // Boss common entry (st07bs 27-28): setHurtbox/setHitbox 48x48 -> r=24.
    set_hitbox(24fx);
    set_hurtbox(24fx);
    set_self_int(1, 0);                       // 0 = emitting, 1 = stopped

    // 702-713: movePosTime(60,4,0,128) is zero displacement from the Boss
    // common (0,128) start; playSound/setInvuln/anm are shell or presentation.
    wait(60);                                 // 713
    // 714 moveLimit(0,128,280,64) begins here; no motion before moveRand.
    wait(80);                                 // 719

    spawn boss7_at();                         // 720
    spawn boss7_at2();                        // 721

    // 722-728: wait(120) then moveRand(60,4,1.0), repeating.
    wait(120);                                // source 140 -> 260
    var t: int = 260;
    while t < SOURCE_END {
        card_move_rand();
        var w: int = SOURCE_END - t;
        if w > 120 { w = 120; }
        card_wait(w);
        t = t + w;
    }
    set_self_int(1, 1);                       // native slot0 timeout at 3000
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 13500, 0, 0, 0, boss7_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
